/** 认不出平台时的兜底（自建网关） */
const FALLBACK: ModelBrandIcon = MODEL_BRAND_ICONS.custom!

/**
 * 模型 → 平台 key（照抄 DEMO 的 detectPlatform 规则，保证同一模型在两边认成同一家）。
 *
 * 先看 modelId 前缀（deepseek-* / gpt-* / claude-* …），再看 provider 关键字
 *（openrouter 上的 anthropic/claude-* 靠这条落到 Claude）。
 */
/**
 * 网关 / 供应商前缀：自建网关会把真实模型名挂在 `auto/`、`workbuddy-ai/` 这类命名空间下。
 * 先剥掉再认，否则 hy3、glm-5.2 会整批落到「自建网关」。
 */
const GATEWAY_PREFIXES = [
  'auto/',
  'workbuddy-ai/',
  'kiro/',
  'accounts/fireworks/models/',
  'deepseek-ai/',
  'moonshotai/',
  'pro/moonshotai/',
  'zai-org/',
  'qwen/',
  'tencent/',
  'x-ai/',
  'openai/',
  'anthropic/',
  'google/',
  'deepseek/',
  'minimax/',
  'z-ai/',
  'zhipu/',
  'kimi/',
]

/** 去掉供应商 / 网关前缀（大小写不敏感，可能叠加多层） */
export function stripProviderPrefix(modelId: string): string {
  let s = String(modelId ?? '').trim()
  let changed = true
  while (changed) {
    changed = false
    const lower = s.toLowerCase()
    for (const p of GATEWAY_PREFIXES) {
      if (s.length > p.length && lower.startsWith(p)) {
        s = s.slice(p.length)
        changed = true
        break
      }
    }
  }
  return s
}

/**
 * 模型 → 平台 key。
 *
 * 顺序：先剥网关前缀，再按模型名认家族，最后才看 provider。
 * 用户口径（2026-11-07）：HY3 / HY4 就是腾讯混元，不能落到「自建网关」；
 * 视频 / 生图模型（Seedance、Veo、可灵…）也要各自认出来，不能全并到豆包。
 */
export function detectPlatform(modelId: string, provider: string): string {
  const s = stripProviderPrefix(modelId).toLowerCase()
  const p = String(provider ?? '').toLowerCase()
  const rules: Array<[RegExp, string]> = [
    // 平台名先于模型名：Dola 上的 Seedance 属于 Dola 渠道（用户 2026-11-07 确认按来源平台显示）
    [/^dola/, 'dola'],
    // 视频 / 生图：必须先于对话模型，否则 seedream 会被当成豆包、veo 会被当成 gemini
    [/seedance/, 'seedance'],
    [/seedream|即梦/, 'doubao'],
    [/^(veo|veo-?[0-9])/, 'veo'],
    [/^sora/, 'sora'],
    [/^kling|可灵/, 'kling'],
    [/^hailuo|海螺/, 'hailuo'],
    [/^runway|^gen-?[0-9]/, 'runway'],
    [/^pika/, 'pika'],
    [/^luma|dream ?machine/, 'luma'],
    [/^vidu/, 'vidu'],
    [/^pixverse/, 'pixverse'],
    [/^dola/, 'dola'],
    [/^cogvideo/, 'cogvideo'],
    [/^kolors|可图/, 'kolors'],
    [/^midjourney|^mj/, 'midjourney'],
    // 对话模型
    [/^(hy|hunyuan)/, 'hunyuan'],
    [/^(gpt|chatgpt|o[1-9](-|$))/, 'openai'],
    [/^claude/, 'claude'],
    [/^gemini/, 'gemini'],
    [/^(deepseek|ds-)/, 'deepseek'],
    [/^(qwen|qwq|qvq|tongyi)/, 'qwen'],
    [/^(glm|chatglm|zhipu|zai)/, 'zhipu'],
    [/^(kimi|moonshot)/, 'kimi'],
    [/^grok/, 'grok'],
    [/^(minimax|abab)/, 'minimax'],
    [/^(ernie|wenxin)/, 'wenxin'],
    [/^(step-|stepfun)/, 'stepfun'],
    [/^yi[-. ]?[0-9]|^yi$/, 'yi'],
    [/^(mistral|codestral|mixtral)/, 'mistral'],
    [/^(doubao|ep-|seed-)/, 'doubao'],
  ]
  for (const [re, key] of rules) if (re.test(s)) return key

  const sp = s + ' ' + p
  if (/deepseek/.test(sp)) return 'deepseek'
  if (/anthropic|claude/.test(p)) return 'claude'
  if (/google|vertex|gemini/.test(p)) return 'gemini'
  if (/openai|azure/.test(p)) return 'openai'
  if (/dashscope|alibaba|qwen/.test(p)) return 'qwen'
  if (/zhipu|bigmodel/.test(p)) return 'zhipu'
  if (/moonshot|kimi/.test(p)) return 'kimi'
  if (/xai|grok/.test(p)) return 'grok'
  if (/minimax/.test(p)) return 'minimax'
  if (/tencent|hunyuan/.test(p)) return 'hunyuan'
  if (/baidu|wenxin/.test(p)) return 'wenxin'
  if (/stepfun/.test(p)) return 'stepfun'
  if (/lingyi|01\.ai|01ai/.test(p)) return 'yi'
  if (/mistral/.test(p)) return 'mistral'
  if (/seed|doubao|volc/.test(sp)) return 'doubao'
  return 'custom'
}

/**
 * 同一张图标会在列表里重复出现（每个模型一行）。
 * SVG 渐变靠 `url(#id)` 引用，**id 重复时浏览器只认第一个**，
 * 而第一个常在隐藏视图里 —— 那一行就变成空白（2026-11-07 实测 MiniMax / 阶跃）。
 * 所以每取一次图就给它一套独立 id。
 */
let iconSeq = 0

function uniqueIds(body: string): string {
  if (!body.includes('id=')) return body
  iconSeq += 1
  const suffix = '-g' + iconSeq
  return body
    .replace(/id="([^"]+)"/g, (_m, id: string) => 'id="' + id + suffix + '"')
    .replace(/url\(#([^)]+)\)/g, (_m, id: string) => 'url(#' + id + suffix + ')')
}

/** 平台 key → 完整 `<svg>` 字符串（卡片里 `v-html` 用；尺寸由 CSS 管） */
export function brandSvg(platform: string): string {
  const icon = MODEL_BRAND_ICONS[platform] ?? FALLBACK
  // Dola 官方只给 PNG：内联 <image>，不能套 currentColor
  if (icon.svg.startsWith('<image ')) {
    return '<svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">' + icon.svg + '</svg>'
  }
  return '<svg viewBox="0 0 24 24" aria-hidden="true">' + uniqueIds(icon.svg) + '</svg>'
}

/** 平台 key → 展示名（分栏左列与卡片副行用；认不出给「自建网关」） */
export function brandName(platform: string): string {
  return (MODEL_BRAND_ICONS[platform] ?? FALLBACK).name
}

/** 当前有图标的平台（诊断 / 测试用） */
export function brandPlatforms(): string[] {
  return Object.keys(MODEL_BRAND_ICONS)
}

